CustomField.formula:
IF(
  AND(
    NOT(ISBLANK(Break_Start_Date__c)),
    NOT(ISBLANK(Break_Start_Time__c)),
    NOT(ISBLANK(Break_End_Date__c)),
    NOT(ISBLANK(Break_End_Time__c))
  ),
  TEXT(
    FLOOR(
      ( 
        DATETIMEVALUE(
          TEXT(Break_End_Date__c) & " " & 
          LEFT(TEXT(Break_End_Time__c), 8)
        ) 
        -
        DATETIMEVALUE(
          TEXT(Break_Start_Date__c) & " " & 
          LEFT(TEXT(Break_Start_Time__c), 8)
        )
      ) * 24
    )
  ) & ":" &
  LPAD(
    TEXT(
      FLOOR(
        MOD(
          ( 
            DATETIMEVALUE(
              TEXT(Break_End_Date__c) & " " & 
              LEFT(TEXT(Break_End_Time__c), 8)
            ) 
            -
            DATETIMEVALUE(
              TEXT(Break_Start_Date__c) & " " & 
              LEFT(TEXT(Break_Start_Time__c), 8)
            )
          ) * 1440, 
          60
        )
      )
    ), 2, "0"
  ),
  ""
)
